import { Autoplay, Keyboard, Navigation, Pagination } from "swiper/modules";
import { Swiper, SwiperSlide } from "swiper/react";
import "swiper/css";
import "swiper/css/navigation";
import "swiper/css/pagination";

import { CoverWrapper } from "../covers/CoverWrapper";
import { GreetingPage } from "../GreetingPage";
import type { LayoutViewProps } from "../types";

/**
 * Carousel layout. Autoplay is delegated to Swiper's own Autoplay module rather
 * than an external timer, and `dir="rtl"` makes Swiper compute slide order and
 * navigation arrows in Hebrew reading direction natively.
 */
export function SliderView({
  album,
  slides,
  autoplay,
  autoplaySpeed,
  loop,
  showControls,
  onPageChange,
}: LayoutViewProps) {
  return (
    <div className="ae-slider">
      <Swiper
        dir="rtl"
        modules={[Navigation, Pagination, Keyboard, Autoplay]}
        navigation={showControls}
        pagination={showControls ? { clickable: true } : false}
        keyboard={{ enabled: true }}
        loop={loop && slides.length > 2}
        autoplay={
          autoplay
            ? {
                delay: Math.max(500, autoplaySpeed),
                disableOnInteraction: false,
                pauseOnMouseEnter: true,
              }
            : false
        }
        spaceBetween={24}
        slidesPerView={1}
        onSlideChange={(swiper) => onPageChange?.(swiper.realIndex)}
        className="ae-slider__swiper"
      >
        {slides.map((slide) => (
          <SwiperSlide key={slide.key} className="ae-slider__slide">
            {slide.kind === "page" ? (
              <GreetingPage album={album} page={slide.page} />
            ) : (
              <CoverWrapper
                album={album}
                face={slide.kind === "front-cover" ? "front" : "back"}
              />
            )}
          </SwiperSlide>
        ))}
      </Swiper>
    </div>
  );
}
